type MSMERegistrationForm = {
  // Basic Company Information
  companyName: string;
  companyType: string;
  industry: string;
  businessDomain: string;
  establishmentYear: string;
  
  // MSME Registration Details — provide Udyog (UDYAM) and/or CIN
  udyamRegistrationNumber: string;
  cinNumber: string;
  gstNumber: string;
  panNumber: string;
  
  // Contact Information
  email: string;
  phone: string;
  
  // Address Information
  address: string;
  city: string;
  state: string;
  pincode: string;
  country: string;
  
  // Business Details
  annualTurnover: string;
  numberOfEmployees: string;
  manufacturingUnits: string;
  primaryProducts: string;
  
  // Environmental Compliance
  hasEnvironmentalClearance: boolean;
  hasPollutionControlBoard: boolean;
  hasWasteManagement: boolean;

  // Manufacturing carbon-profile fields
  msmeType: string;
  industrySector: string;
  nicCode: string;
  yearOfEstablishment: string;
  locationCity: string;
  locationState: string;
  locationCountry: string;
  plantAreaSqft: string;
  operationalDaysPerYear: string;
  primaryEnergySource: string;
  backupEnergySource: string;
  mainFuelsUsed: string;
  waterSource: string;
  wasteManagementPractice: string;
  keyProducts: string;
  productionCapacityPerMonth: string;
  productionCapacityUnit: string;
  supplyChainType: string;
  logisticsMode: string;
  certifications: string;
  esgMaturityLevel: string;
  digitalizationLevel: string;
  carbonAccountingPractice: string;
  regulatoryExposure: string;
  exportActivity: boolean | null;
  clusterAssociation: string;
};

