type HttpLikeError = Error & {
  status?: number;
  response?: { status?: number; data?: unknown };
};

const MSME_REGISTRATION_MESSAGE_TO_FIELD: Record<string, string> = {
  'company name is required': 'companyName',
  'company name cannot be empty': 'companyName',
  'valid company type is required': 'companyType',
  'invalid company type': 'companyType',
  'industry is required': 'industry',
  'industry cannot be empty': 'industry',
  'valid business domain is required': 'businessDomain',
  'invalid business domain': 'businessDomain',
  'udyog (udyam) registration number is required': 'udyamRegistrationNumber',
  'invalid udyam registration number format': 'udyamRegistrationNumber',
  'invalid gst number format': 'gstNumber',
  'invalid pan number format': 'panNumber',
  'valid email is required': 'email',
  'valid contact email is required': 'email',
  'phone is required': 'phone',
  'contact phone cannot be empty': 'phone',
  'annual turnover must be a number': 'annualTurnover',
  'number of employees must be an integer': 'numberOfEmployees',
  'number of manufacturing units must be an integer': 'manufacturingUnits',
  'msme profile already exists': 'companyName',
};

const normalizeValidationMessage = (value: unknown): string => {
  if (typeof value === 'string') {
    return value.trim();
  }
  if (value && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    if (typeof record.msg === 'string') {
      return record.msg.trim();
    }
    if (typeof record.message === 'string') {
      return record.message.trim();
    }
  }
  return '';
};

export const extractValidationMessages = (responseBody: unknown): string[] => {
  if (!responseBody || typeof responseBody !== 'object') {
    return [];
  }
  const record = responseBody as Record<string, unknown>;
  if (!Array.isArray(record.errors)) {
    return [];
  }
  return record.errors
    .map(normalizeValidationMessage)
    .filter((message) => message.length > 0);
};

export const formatValidationErrorMessage = (
  responseBody: unknown,
  fallbackMessage = 'Please fix the highlighted fields and try again.'
): string => {
  const messages = extractValidationMessages(responseBody);
  if (messages.length === 0) {
    return fallbackMessage;
  }
  if (messages.length === 1) {
    return messages[0];
  }
  return messages.join(' ');
};

export const mapMsmeRegistrationFieldErrors = (
  messages: string[]
): Record<string, string> => {
  const fieldErrors: Record<string, string> = {};
  messages.forEach((message) => {
    const normalized = message.toLowerCase();
    const field = MSME_REGISTRATION_MESSAGE_TO_FIELD[normalized];
    if (field) {
      fieldErrors[field] = message;
      return;
    }
    if (normalized.includes('gst')) {
      fieldErrors.gstNumber = message;
    } else if (normalized.includes('pan')) {
      fieldErrors.panNumber = message;
    } else if (normalized.includes('udyam') || normalized.includes('udyog')) {
      fieldErrors.udyamRegistrationNumber = message;
    } else if (normalized.includes('email')) {
      fieldErrors.email = message;
    } else if (normalized.includes('phone')) {
      fieldErrors.phone = message;
    } else if (normalized.includes('turnover')) {
      fieldErrors.annualTurnover = message;
    } else if (normalized.includes('employee')) {
      fieldErrors.numberOfEmployees = message;
    } else if (normalized.includes('manufacturing unit')) {
      fieldErrors.manufacturingUnits = message;
    } else if (normalized.includes('company type')) {
      fieldErrors.companyType = message;
    } else if (normalized.includes('business domain')) {
      fieldErrors.businessDomain = message;
    } else if (normalized.includes('industry')) {
      fieldErrors.industry = message;
    } else if (normalized.includes('company name')) {
      fieldErrors.companyName = message;
    }
  });
  return fieldErrors;
};

export const extractMsmeRegistrationFieldErrors = (
  error: unknown
): Record<string, string> => {
  if (!(error instanceof Error)) {
    return {};
  }
  const httpError = error as HttpLikeError;
  const responseBody = httpError.response?.data;
  const messages = extractValidationMessages(responseBody);
  if (messages.length === 0) {
    return {};
  }
  return mapMsmeRegistrationFieldErrors(messages);
};

export const resolveApiErrorMessage = (error: unknown, fallback: string): string => {
  if (!(error instanceof Error)) {
    return fallback;
  }
  const httpError = error as HttpLikeError;
  const responseBody = httpError.response?.data;
  const validationMessage = formatValidationErrorMessage(responseBody, '');
  if (validationMessage) {
    return validationMessage;
  }
  return error.message || fallback;
};
